<?php
declare(strict_types=1);namespace App\Infrastructure\Discovery;use App\Application\Discovery\Port\WebDiscoveryProviderInterface;use App\Domain\Discovery\ValueObject\DiscoveredResource;use App\Infrastructure\Database;final class ConfiguredWebDiscoveryProvider implements WebDiscoveryProviderInterface{public function name():string{return 'configured-web';}public function search(string $query,string $type):array{$base=Database::env('DISCOVERY_PROVIDER_BASE_URL');$allowed=array_filter(array_map('trim',explode(',',Database::env('DISCOVERY_ALLOWED_HOSTS'))));$host=parse_url($base,PHP_URL_HOST);if(!is_string($host)||$base===''||!in_array($host,$allowed,true))throw new \DomainException('Provider de descoberta nao esta configurado com um host permitido.');$url=$base.(str_contains($base,'?')?'&':'?').http_build_query(['query'=>$query,'resource_type'=>$type]);$context=stream_context_create(['http'=>['timeout'=>4,'ignore_errors'=>true,'follow_location'=>0,'header'=>'Accept: application/json\r\n']]);$body=@file_get_contents($url,false,$context);if($body===false)throw new \DomainException('O provider de descoberta nao respondeu.');try{$data=json_decode($body,true,512,JSON_THROW_ON_ERROR);}catch(\JsonException){throw new \DomainException('O provider retornou formato invalido.');}$items=$data['items']??null;if(!is_array($items))throw new \DomainException('O provider nao retornou candidatos.');$out=[];foreach($items as $item){if(!is_array($item)||!is_string($item['title']??null)||!is_string($item['url']??null)||filter_var($item['url'],FILTER_VALIDATE_URL)===false)continue;$candidateHost=parse_url($item['url'],PHP_URL_HOST);if(!is_string($candidateHost)||!in_array($candidateHost,$allowed,true))continue;$out[]=new DiscoveredResource($type,mb_substr(trim($item['title']),0,255),$item['url']);}return $out;}}
